import { Hono } from 'hono'
import crypto from 'crypto'
import { db } from '@/db/index.js'
import { supplierOrders, supplierOrderLines, stockMovements } from '@/db/schema.js'
import type { NewSupplierOrder, NewSupplierOrderLine, NewStockMovement } from '@/db/schema.js'
import { eq, and, desc, count as drizzleCount, inArray } from 'drizzle-orm'

const supplierOrdersRoutes = new Hono()

// ============================================================================
// Types
// ============================================================================

type SupplierOrderStatus = 'pending' | 'ordered' | 'received'

interface CreateSupplierOrderInput {
  supplierName: string
  items: Array<{ eanUpc: string; quantityOrdered: number }>
}

// ============================================================================
// Valid status transitions
// ============================================================================

const VALID_TRANSITIONS: Record<SupplierOrderStatus, SupplierOrderStatus[]> = {
  pending: ['ordered'],
  ordered: ['received'],
  received: [] // terminal state — no further transitions
}

function isValidTransition(current: string, next: string): boolean {
  const allowed = VALID_TRANSITIONS[current as SupplierOrderStatus]
  return Array.isArray(allowed) && allowed.includes(next as SupplierOrderStatus)
}

// ============================================================================
// Duplicate merge helper (AC2)
// ============================================================================

/** Merge items with duplicate eanUpc, summing quantityOrdered. */
function mergeDuplicateItems(items: CreateSupplierOrderInput['items']): Map<string, number> {
  const merged = new Map<string, number>()
  for (const item of items) {
    const existing = merged.get(item.eanUpc) ?? 0
    merged.set(item.eanUpc, existing + item.quantityOrdered)
  }
  return merged
}

// ============================================================================
// GET /supplier-orders — List orders with filters (AC5)
// ============================================================================

supplierOrdersRoutes.get('/', async (c) => {
  const supplierName = c.req.query('supplierName') as string | undefined
  const status = c.req.query('status') as string | undefined
  const limit = parseInt(c.req.query('limit') ?? '20', 10)

  try {
    // Build WHERE clause
    const conditions: unknown[] = []
    if (supplierName) conditions.push(eq(supplierOrders.supplierName, supplierName))
    if (status) conditions.push(eq(supplierOrders.status, status as SupplierOrderStatus))

    const whereClause: ReturnType<typeof eq> | undefined = conditions.length > 0
      ? (and(...conditions as Parameters<typeof and>) as ReturnType<typeof eq>)
      : undefined

    // Get total count
    const [{ total }] = await db
      .select({ total: drizzleCount() })
      .from(supplierOrders)
      .where(whereClause)

    // Get orders with line counts, newest first
    const ordersWithCounts = await db
      .select({
        id: supplierOrders.id,
        supplierName: supplierOrders.supplierName,
        status: supplierOrders.status,
        referenceNumber: supplierOrders.referenceNumber,
        orderedAt: supplierOrders.orderedAt,
        createdAt: supplierOrders.createdAt,
        lineCount: drizzleCount(supplierOrderLines.orderId)
      })
      .from(supplierOrders)
      .leftJoin(supplierOrderLines, eq(supplierOrders.id, supplierOrderLines.orderId))
      .where(whereClause)
      .groupBy(
        supplierOrders.id,
        supplierOrders.supplierName,
        supplierOrders.status,
        supplierOrders.referenceNumber,
        supplierOrders.orderedAt,
        supplierOrders.createdAt
      )
      .orderBy(desc(supplierOrders.createdAt))
      .limit(limit)

    return c.json({ orders: ordersWithCounts, total })
  } catch (err) {
    console.error('[GET /supplier-orders] Unexpected error:', err)
    return c.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ============================================================================
// GET /supplier-orders/:id — Get order detail with lines
// ============================================================================

supplierOrdersRoutes.get('/:id', async (c) => {
  const id = c.req.param('id')

  try {
    // Fetch order
    const [order] = await db.select().from(supplierOrders).where(eq(supplierOrders.id, id))
    if (!order) {
      return c.json({ error: 'Supplier order not found', code: 'NOT_FOUND' }, 404)
    }

    // Fetch lines for this order
    const lines = await db.select().from(supplierOrderLines).where(eq(supplierOrderLines.orderId, id))

    return c.json({ order, lines })
  } catch (err) {
    console.error('[GET /supplier-orders/:id] Unexpected error:', err)
    return c.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ============================================================================
// POST /supplier-orders — Create supplier order from items (AC1, AC2)
// ============================================================================

supplierOrdersRoutes.post('/', async (c) => {
  const input = await c.req.json() as CreateSupplierOrderInput | undefined

  try {
    // Validate required fields
    if (!input || typeof input !== 'object') {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const { supplierName, items } = input
    if (!supplierName || !items || !Array.isArray(items) || items.length === 0) {
      return c.json({ error: 'supplierName and non-empty items array are required', code: 'VALIDATION_ERROR' }, 400)
    }

    // Validate each item has eanUpc and quantityOrdered
    for (const item of items) {
      if (!item.eanUpc || typeof item.quantityOrdered !== 'number' || item.quantityOrdered < 1) {
        return c.json({ error: 'Each item must have a valid eanUpc and quantityOrdered >= 1', code: 'VALIDATION_ERROR' }, 400)
      }
    }

    // Merge duplicates (AC2)
    const mergedItems = mergeDuplicateItems(items)

    // Create order
    const orderId = crypto.randomUUID()
    const newOrder: NewSupplierOrder = {
      id: orderId,
      supplierName,
      status: 'pending'
    }
    await db.insert(supplierOrders).values(newOrder)

    // Create lines from merged items
    const linesToInsert: NewSupplierOrderLine[] = []
    for (const [eanUpc, quantityOrdered] of mergedItems.entries()) {
      linesToInsert.push({
        id: crypto.randomUUID(),
        orderId,
        eanUpc,
        quantityOrdered
      })
    }

    if (linesToInsert.length > 0) {
      await db.insert(supplierOrderLines).values(linesToInsert)
    }

    // Fetch and return the created order with lines
    const [createdOrder] = await db.select().from(supplierOrders).where(eq(supplierOrders.id, orderId))
    const createdLines = await db.select().from(supplierOrderLines).where(eq(supplierOrderLines.orderId, orderId))

    return c.json({ order: createdOrder, lines: createdLines }, 201)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    console.error('[POST /supplier-orders] Unexpected error:', err)
    return c.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ============================================================================
// PATCH /supplier-orders/:id/status — Status transitions (AC3)
// ============================================================================

supplierOrdersRoutes.patch('/:id/status', async (c) => {
  const id = c.req.param('id')
  const input = await c.req.json() as { status: string } | undefined

  try {
    if (!input || !input.status) {
      return c.json({ error: 'status is required', code: 'VALIDATION_ERROR' }, 400)
    }

    // Validate status value
    const validStatuses = ['pending', 'ordered', 'received'] as const
    if (!validStatuses.includes(input.status as SupplierOrderStatus)) {
      return c.json({ error: `Invalid status. Must be one of: ${validStatuses.join(', ')}`, code: 'VALIDATION_ERROR' }, 400)
    }

    // Fetch current order
    const [order] = await db.select().from(supplierOrders).where(eq(supplierOrders.id, id))
    if (!order) {
      return c.json({ error: 'Supplier order not found', code: 'NOT_FOUND' }, 404)
    }

    // Validate transition (AC3)
    if (!isValidTransition(order.status, input.status as SupplierOrderStatus)) {
      return c.json({
        error: `Cannot transition from '${order.status}' to '${input.status}'. Valid transitions: ${VALID_TRANSITIONS[order.status as SupplierOrderStatus].join(', ') || 'none (terminal)'}`,
        code: 'INVALID_STATUS_TRANSITION'
      }, 409)
    }

    // Set orderedAt timestamp when transitioning to 'ordered'
    const updates: Partial<NewSupplierOrder> = { status: input.status as SupplierOrderStatus }
    if (input.status === 'ordered') {
      updates.orderedAt = new Date()
    }

    await db.update(supplierOrders).set(updates).where(eq(supplierOrders.id, id))

    // Fetch updated order
    const [updatedOrder] = await db.select().from(supplierOrders).where(eq(supplierOrders.id, id))

    return c.json({ order: updatedOrder })
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    console.error('[PATCH /supplier-orders/:id/status] Unexpected error:', err)
    return c.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ============================================================================
// POST /supplier-orders/:id/receive — Receive stock (AC4)
// ============================================================================

supplierOrdersRoutes.post('/:id/receive', async (c) => {
  const id = c.req.param('id')

  try {
    // Fetch order
    const [order] = await db.select().from(supplierOrders).where(eq(supplierOrders.id, id))
    if (!order) {
      return c.json({ error: 'Supplier order not found', code: 'NOT_FOUND' }, 404)
    }

    // Must be in 'ordered' status to receive (AC3 — transition check)
    if (order.status !== 'ordered') {
      return c.json({
        error: `Cannot receive stock. Order must be in 'ordered' status (current: '${order.status}')`,
        code: 'INVALID_STATUS_TRANSITION'
      }, 409)
    }

    // Fetch all lines for this order
    const lines = await db.select().from(supplierOrderLines).where(eq(supplierOrderLines.orderId, id))

    if (lines.length === 0) {
      return c.json({ error: 'No line items to receive', code: 'NO_LINES' }, 400)
    }

    // Check all lines have partId set (AC4 — import required first)
    const unimportedLines = lines.filter(line => !line.partId)
    if (unimportedLines.length > 0) {
      return c.json({
        error: 'Cannot receive stock. All line items must be imported into the local catalog first.',
        code: 'UNIMPORTED_LINES',
        unimportedEans: unimportedLines.map(l => l.eanUpc)
      }, 409)
    }

    // Create stock movements and update quantityReceived for each line
    const stockMovementsToInsert: NewStockMovement[] = []
    const linesToUpdate: Array<{ id: string; quantityReceived: number }> = []

    for (const line of lines) {
      if (!line.partId) continue // should not happen after check above, but safety guard

      const qtyToReceive = line.quantityOrdered - line.quantityReceived
      if (qtyToReceive <= 0) continue // already fully received

      stockMovementsToInsert.push({
        id: crypto.randomUUID(),
        partId: line.partId,
        quantityDelta: qtyToReceive,
        reason: 'order_receive',
        referenceType: 'supplier_order_line',
        referenceId: line.id
      })

      linesToUpdate.push({
        id: line.id,
        quantityReceived: line.quantityReceived + qtyToReceive
      })
    }

    // Insert stock movements
    if (stockMovementsToInsert.length > 0) {
      await db.insert(stockMovements).values(stockMovementsToInsert)
    }

    // Update line quantities received
    for (const update of linesToUpdate) {
      await db.update(supplierOrderLines)
        .set({ quantityReceived: update.quantityReceived })
        .where(eq(supplierOrderLines.id, update.id))
    }

    // Transition order to 'received'
    await db.update(supplierOrders).set({ status: 'received' }).where(eq(supplierOrders.id, id))

    // Fetch updated state
    const [updatedOrder] = await db.select().from(supplierOrders).where(eq(supplierOrders.id, id))
    const movementsCreated = await db.select()
      .from(stockMovements)
      .where(
        and(
          eq(stockMovements.referenceType, 'supplier_order_line'),
          inArray(stockMovements.referenceId, lines.map(l => l.id))
        )
      )

    return c.json({ order: updatedOrder, stockMovements: movementsCreated })
  } catch (err) {
    console.error('[POST /supplier-orders/:id/receive] Unexpected error:', err)
    return c.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, 500)
  }
})

export default supplierOrdersRoutes

/**
 * Supplier Orders feature API client.
 */

import type {
  SupplierOrder,
  SupplierOrderListItem,
  SupplierOrderLine,
  CreateSupplierOrderFormData,
  StockMovementResult,
} from './types.js'

// ---------------------------------------------------------------------------
// Types for request/response shapes
// ---------------------------------------------------------------------------

export interface SupplierOrdersListResponse {
  orders: SupplierOrderListItem[]
  total: number
}

export interface CreateSupplierOrderResponse {
  order: SupplierOrder
  lines: SupplierOrderLine[]
}

export interface SupplierOrderDetailResponse {
  order: SupplierOrder
  lines: SupplierOrderLine[]
}

export interface ReceiveStockResponse {
  order: SupplierOrder
  stockMovements: StockMovementResult[]
}

// ---------------------------------------------------------------------------
// API Functions — Order CRUD
// ---------------------------------------------------------------------------

/** Get paginated supplier orders list with optional filters. */
export async function getSupplierOrders(
  params?: { statusFilter?: string; supplierName?: string; limit?: number }
): Promise<SupplierOrdersListResponse> {
  const searchParams = new URLSearchParams()
  if (params?.statusFilter) searchParams.set('status', params.statusFilter)
  if (params?.supplierName) searchParams.set('supplierName', params.supplierName)
  if (params?.limit) searchParams.set('limit', String(params.limit))

  const queryString = searchParams.toString()
  const url = queryString ? `/api/supplier-orders?${queryString}` : '/api/supplier-orders'

  const response = await fetch(url)
  if (!response.ok) {
    throw new Error('Failed to fetch supplier orders')
  }
  return response.json()
}

/** Get a single supplier order by ID with line items. */
export async function getSupplierOrder(id: string): Promise<SupplierOrderDetailResponse> {
  const response = await fetch(`/api/supplier-orders/${id}`)
  if (!response.ok) {
    throw new Error('Failed to fetch supplier order')
  }
  return response.json()
}

/** Create a new supplier order from items. */
export async function createSupplierOrder(
  input: CreateSupplierOrderFormData
): Promise<CreateSupplierOrderResponse> {
  const response = await fetch('/api/supplier-orders', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to create supplier order' }))
    throw new Error(error.error || 'Failed to create supplier order')
  }

  return response.json()
}

// ---------------------------------------------------------------------------
// API Functions — Status Transitions
// ---------------------------------------------------------------------------

/** Transition a supplier order's status (e.g. pending → ordered). */
export async function updateSupplierOrderStatus(
  id: string,
  status: string
): Promise<{ order: SupplierOrder }> {
  const response = await fetch(`/api/supplier-orders/${id}/status`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ status }),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to update order status' }))
    throw new Error(error.error || 'Failed to update order status')
  }

  return response.json()
}

// ---------------------------------------------------------------------------
// API Functions — Receive Stock
// ---------------------------------------------------------------------------

/** Receive stock for an ordered supplier order. Creates stock movements. */
export async function receiveSupplierOrder(id: string): Promise<ReceiveStockResponse> {
  const response = await fetch(`/api/supplier-orders/${id}/receive`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to receive stock' }))
    throw new Error(error.error || 'Failed to receive stock')
  }

  return response.json()
}

/**
 * Supplier Orders feature types — mirrors API response shapes for frontend use.
 */

// ============================================================================
// Supplier Order Status
// ============================================================================

export type SupplierOrderStatus = 'pending' | 'ordered' | 'received'

/** Color mapping for status badges */
export const SUPPLIER_ORDER_STATUS_COLORS: Record<SupplierOrderStatus, string> = {
  pending: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400',
  ordered: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400',
  received: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400',
}

// ============================================================================
// Supplier Order Shape (matches API response)
// ============================================================================

export interface SupplierOrder {
  id: string
  supplierName: string
  status: SupplierOrderStatus
  referenceNumber: string | null
  orderedAt: number | null
  createdAt: number
}

/** Compact order shape for list display */
export interface SupplierOrderListItem extends SupplierOrder {
  lineCount?: number
}

// ============================================================================
// Line Item Shape (matches API response)
// ============================================================================

export interface SupplierOrderLine {
  id: string
  orderId: string
  eanUpc: string
  partId: string | null
  quantityOrdered: number
  quantityReceived: number
}

// ============================================================================
// Stock Movement Shape (from receive response)
// ============================================================================

export interface StockMovementResult {
  id: string
  partId: string
  quantityDelta: number
  reason: string
  referenceType: string | null
  referenceId: string | null
}

// ============================================================================
// Create Order Form Data
// ============================================================================

/** A single item to add to a supplier order */
export interface OrderItemInput {
  eanUpc: string
  quantityOrdered: number
}

/** Form data for creating a new supplier order */
export interface CreateSupplierOrderFormData {
  supplierName: string
  items: OrderItemInput[]
}

/** Default empty form state */
export const createEmptySupplierOrderForm = (): CreateSupplierOrderFormData => ({
  supplierName: '',
  items: []
})

// ============================================================================
// Supplier Names (from Product Finder)
// ============================================================================

export const SUPPLIER_NAMES = ['dst', 'gransier', 'kruitbosch'] as const
export type SupplierName = typeof SUPPLIER_NAMES[number]

/** Label mapping for supplier names */
export const SUPPLIER_LABELS: Record<SupplierName, string> = {
  dst: 'DST',
  gransier: 'Gransier',
  kruitbosch: 'Kruitbosch'
}

import { describe, it, expect, beforeEach } from 'vitest'
import app from '@/app.js'
import { db } from '@/db/index.js'
import { supplierOrders, supplierOrderLines, stockMovements, parts, vatRates } from '@/db/schema.js'
import { eq } from 'drizzle-orm'

// ---------------------------------------------------------------------------
// Type definitions for API responses
// ---------------------------------------------------------------------------

type CreateSupplierOrderResponse = {
  order: Record<string, unknown>
  lines: Record<string, unknown>[]
}

type SupplierOrdersListResponse = {
  orders: Record<string, unknown>[]
  total: number
}

type SupplierOrderDetailResponse = {
  order: Record<string, unknown>
  lines: Record<string, unknown>[]
}

type ReceiveStockResponse = {
  order: Record<string, unknown>
  stockMovements: Record<string, unknown>[]
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

async function resetTables() {
  await db.delete(stockMovements)
  await db.delete(supplierOrderLines)
  await db.delete(supplierOrders)
  await db.delete(parts)
  await db.delete(vatRates)
}

describe('Supplier Orders Routes — Integration Tests', () => {
  beforeEach(async () => {
    await resetTables()
  })

  // ---------------------------------------------------------------------------
  // POST /api/supplier-orders — Create supplier order from items
  // ---------------------------------------------------------------------------
  describe('POST /api/supplier-orders', () => {
    it('[tracer] should create a supplier order with lines and return them (AC1)', async () => {
      const body = {
        supplierName: 'dst',
        items: [
          { eanUpc: '8712345678901', quantityOrdered: 2 },
          { eanUpc: '8712345678902', quantityOrdered: 5 }
        ]
      }

      const res = await app.request('/api/supplier-orders', {
        method: 'POST',
        body: JSON.stringify(body),
        headers: { 'Content-Type': 'application/json' }
      })

      expect(res.status).toBe(201)

      const json = await res.json() as CreateSupplierOrderResponse
      expect(json.order).toBeDefined()
      expect(json.lines).toHaveLength(2)

      // Verify order has correct supplier and status
      const order = json.order as Record<string, unknown>
      expect(order.supplierName).toBe('dst')
      expect(order.status).toBe('pending')

      // Verify lines match input
      const lines = json.lines as Array<{ eanUpc: string; quantityOrdered: number }>
      expect(lines[0].eanUpc).toBe('8712345678901')
      expect(lines[0].quantityOrdered).toBe(2)
      expect(lines[1].eanUpc).toBe('8712345678902')
      expect(lines[1].quantityOrdered).toBe(5)

      // Verify DB state
      const dbOrders = await db.select().from(supplierOrders)
      const dbLines = await db.select().from(supplierOrderLines)
      expect(dbOrders).toHaveLength(1)
      expect(dbLines).toHaveLength(2)
    })

    it('should merge duplicate eanUpc within same order (AC2)', async () => {
      const body = {
        supplierName: 'gransier',
        items: [
          { eanUpc: '8710000000001', quantityOrdered: 3 },
          { eanUpc: '8710000000002', quantityOrdered: 1 },
          { eanUpc: '8710000000001', quantityOrdered: 4 } // duplicate — should merge to 7
        ]
      }

      const res = await app.request('/api/supplier-orders', {
        method: 'POST',
        body: JSON.stringify(body),
        headers: { 'Content-Type': 'application/json' }
      })

      expect(res.status).toBe(201)

      const json = await res.json() as CreateSupplierOrderResponse
      // 3 items → 2 unique lines (merged)
      expect(json.lines).toHaveLength(2)

      const lines = json.lines as Array<{ eanUpc: string; quantityOrdered: number }>
      const mergedLine = lines.find(l => l.eanUpc === '8710000000001')
      expect(mergedLine).toBeDefined()
      expect(mergedLine!.quantityOrdered).toBe(7) // 3 + 4

      const otherLine = lines.find(l => l.eanUpc === '8710000000002')
      expect(otherLine!.quantityOrdered).toBe(1)
    })

    it('should reject empty items array with 400', async () => {
      const body = { supplierName: 'dst', items: [] }

      const res = await app.request('/api/supplier-orders', {
        method: 'POST',
        body: JSON.stringify(body),
        headers: { 'Content-Type': 'application/json' }
      })

      expect(res.status).toBe(400)
    })

    it('should reject missing supplierName with 400', async () => {
      const body = { items: [{ eanUpc: '8712345678901', quantityOrdered: 1 }] }

      const res = await app.request('/api/supplier-orders', {
        method: 'POST',
        body: JSON.stringify(body),
        headers: { 'Content-Type': 'application/json' }
      })

      expect(res.status).toBe(400)
    })
  })

  // ---------------------------------------------------------------------------
  // PATCH /api/supplier-orders/:id/status — Status transitions (AC3)
  // ---------------------------------------------------------------------------
  describe('PATCH /api/supplier-orders/:id/status', () => {
    it('should transition pending → ordered', async () => {
      // Create order first
      const createRes = await app.request('/api/supplier-orders', {
        method: 'POST',
        body: JSON.stringify({ supplierName: 'dst', items: [{ eanUpc: '8712345678901', quantityOrdered: 2 }] }),
        headers: { 'Content-Type': 'application/json' }
      })
      const createJson = await createRes.json() as CreateSupplierOrderResponse
      const orderId = (createJson.order as Record<string, unknown>).id as string

      // Transition to ordered
      const res = await app.request(`/api/supplier-orders/${orderId}/status`, {
        method: 'PATCH',
        body: JSON.stringify({ status: 'ordered' }),
        headers: { 'Content-Type': 'application/json' }
      })

      expect(res.status).toBe(200)
      const json = await res.json() as Record<string, unknown>
      expect((json.order as Record<string, unknown>).status).toBe('ordered')
    })

    it('should transition ordered → received', async () => {
      // Create order first
      const createRes = await app.request('/api/supplier-orders', {
        method: 'POST',
        body: JSON.stringify({ supplierName: 'dst', items: [{ eanUpc: '8712345678901', quantityOrdered: 2 }] }),
        headers: { 'Content-Type': 'application/json' }
      })
      const createJson = await createRes.json() as CreateSupplierOrderResponse
      const orderId = (createJson.order as Record<string, unknown>).id as string

      // Transition to ordered first
      await app.request(`/api/supplier-orders/${orderId}/status`, {
        method: 'PATCH',
        body: JSON.stringify({ status: 'ordered' }),
        headers: { 'Content-Type': 'application/json' }
      })

      // Then transition to received
      const res = await app.request(`/api/supplier-orders/${orderId}/status`, {
        method: 'PATCH',
        body: JSON.stringify({ status: 'received' }),
        headers: { 'Content-Type': 'application/json' }
      })

      expect(res.status).toBe(200)
      const json = await res.json() as Record<string, unknown>
      expect((json.order as Record<string, unknown>).status).toBe('received')
    })

    it('should reject invalid transition (e.g. received → pending) with 409', async () => {
      // Create and move to received
      const createRes = await app.request('/api/supplier-orders', {
        method: 'POST',
        body: JSON.stringify({ supplierName: 'dst', items: [{ eanUpc: '8712345678901', quantityOrdered: 2 }] }),
        headers: { 'Content-Type': 'application/json' }
      })
      const createJson = await createRes.json() as CreateSupplierOrderResponse
