      // Seed a part in the catalog
      const partId = 'part-test-001'
      await db.insert(parts).values({ id: partId, barcode: '8712345678901', name: 'Test Bearing', priceNet: 1000 })

      // Create order with line that references the imported part
      const createRes = await app.request('/api/supplier-orders', {
        method: 'POST',
        body: JSON.stringify({ supplierName: 'dst', items: [{ eanUpc: '8712345678901', quantityOrdered: 3 }] }),
