      })
      const createJson = await createRes.json() as CreateSupplierOrderResponse
      const orderId = (createJson.order as Record<string, unknown>).id as string

      // Set partId on the line (simulating import)
      const dbLinesBefore = await db.select().from(supplierOrderLines).where(eq(supplierOrderLines.orderId, orderId))
      expect(dbLinesBefore).toHaveLength(1)
      await db.update(supplierOrderLines)
        .set({ partId })
        .where(eq(supplierOrderLines.id, dbLinesBefore[0].id))

      // Transition to ordered first (receive requires ordered status)
      await app.request(`/api/supplier-orders/${orderId}/status`, {
        method: 'PATCH',
        body: JSON.stringify({ status: 'ordered' }),
        headers: { 'Content-Type': 'application/json' }
