      const createJson = await createRes.json() as CreateSupplierOrderResponse
      const orderId = (createJson.order as Record<string, unknown>).id as string

      // Transition to ordered
      await app.request(`/api/supplier-orders/${orderId}/status`, {
        method: 'PATCH',
        body: JSON.stringify({ status: 'ordered' }),
        headers: { 'Content-Type': 'application/json' }
      })

      // Try to receive — should fail because partId is null
      const res = await app.request(`/api/supplier-orders/${orderId}/receive`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' }
      })

      expect(res.status).toBe(409)
    })

    it('should reject receive when order is not in ordered status', async () => {
      // Create order (stays pending)
      const createRes = await app.request('/api/supplier-orders', {
        method: 'POST',
        body: JSON.stringify({ supplierName: 'dst', items: [{ eanUpc: '8712345678901', quantityOrdered: 2 }] }),
