        <CreateOrderDialog
          isOpen={showCreateDialog}
          onClose={() => setShowCreateDialog(false)}
          onSuccess={(orderId) => {
            toast.success('Supplier order created')
            fetchOrders()
            setSelectedOrderId(orderId)
          }}
        />

        {/* Order Detail Panel */}
        {selectedOrderId && (
          <OrderDetailPanel
            orderId={selectedOrderId}
            onClose={() => setSelectedOrderId(null)}
            onRefresh={fetchOrders}
          />
        )}
      </CardContent>
    </div>
  )
}

